// Question bank built only from the six lecture slide decks.
// Every answer is an economics term, concept or line of reasoning, never a bare number, date or ranking.
// d: 1 = warm-up, 2 = standard, 3 = professor trap.
// MCQ: a = correct answer, w = wrong options. True/False: tf = true|false.
window.LECTURES = [
{
  id: 1, code: "L1", title: "Introduction",
  sub: "What international economics is about, gains from trade, trade policy, the gravity model",
  quip: "Gravity model? More like the gravity of my situation.",
  qs: [
    {t:"Basics", d:1, q:"The study of how nations interact through trade of goods and services, flows of money, and investment is called…", a:"International economics", w:["Public finance","Microeconomics","Development policy"], e:"Slide: 'International economics is about how nations interact through trade of goods and services, flows of money, and investment.'"},
    {t:"Basics", d:2, q:"International trade focuses on ___, while international finance focuses on ___.", a:"Movement of goods and services; financial or monetary transactions", w:["Financial transactions; movement of goods","Tariffs; quotas","Exports; imports"], e:"Trade = goods and services across nations. Finance = financial or monetary transactions across nations."},
    {t:"Basics", d:2, q:"Case: A Japanese carmaker ships cars to the U.S. Which branch of international economics studies this?", a:"International trade", w:["International finance","Monetary policy","Public finance"], e:"Movement of goods across nations = international trade."},
    {t:"Basics", d:2, q:"Case: A Japanese bank buys U.S. government bonds. Which branch of international economics studies this?", a:"International finance", w:["International trade","Industrial policy","Trade policy"], e:"A financial transaction across nations = international finance."},
    {t:"Basics", d:2, q:"Why would a very large country with diverse resources rely LESS on international trade than smaller countries?", a:"It can produce more of what it needs domestically", w:["It always has higher tariffs","Its exchange rate is fixed","It has no gains from trade"], e:"The slides explain the U.S. relies less on trade because of its size and diversity of resources."},
    {t:"Gains from trade", d:1, q:"Countries selling goods and services to each other almost always generate mutual benefits. This idea is called…", a:"Gains from trade", w:["Zero-sum trade","Protectionism","The pattern of trade"], e:"'The most important insight of all international economics is that there are gains from trade.'"},
    {t:"Gains from trade", d:1, q:"Case: Norwegian consumers import oranges they would have a hard time producing. Buyer and seller both end up better off. This shows…", a:"A voluntary transaction can make both sides better off", w:["Imports always hurt the importing country","Trade is a zero-sum game","Only the exporter gains"], e:"Both parties gain from a voluntary exchange."},
    {t:"Gains from trade", d:3, q:"True or false: A country that is the least efficient producer of everything cannot gain from trade.", tf:false, e:"Countries produce what they're most productive at COMPARED TO their other options, then trade. Even the least efficient country gains."},
    {t:"Gains from trade", d:2, q:"Case: A country focuses its finite resources on a few goods it makes well and gets everything else through trade. This is called…", a:"Specialization", w:["Autarky","Protectionism","Diversification"], e:"'Countries can specialize in production, while consuming many goods and services through trade.'"},
    {t:"Gains from trade", d:2, q:"Case: A land-rich country exports farm goods and imports goods that need resources it lacks. Trade lets it…", a:"Export goods made with abundant resources and import goods made with scarce resources", w:["Export goods made with scarce resources","Avoid using its abundant resources","Stop producing anything"], e:"'Trade benefits countries by allowing them to export goods made with relatively abundant resources and import goods made with relatively scarce resources.'"},
    {t:"Gains from trade", d:2, q:"When countries specialize, they may become more efficient because of…", a:"Large-scale production", w:["Higher tariffs","Fixed exchange rates","Export subsidies"], e:"'When countries specialize, they may be more efficient due to large-scale production.'"},
    {t:"Gains from trade", d:2, q:"Case: A country borrows abroad today and repays with future output. Trading current resources for future resources is called…", a:"International borrowing and lending", w:["Service offshoring","Export subsidy","Vertical disintegration"], e:"A source of gains from trade listed on the slides."},
    {t:"Gains from trade", d:3, q:"Case: After trade opens, workers in an industry that competes with imports lose income. This shows that trade can change…", a:"The distribution of income within a country", w:["The pattern of trade","The exchange rate regime","The size of GDP only"], e:"'Trade may therefore affect the distribution of income within a country.'"},
    {t:"Gains from trade", d:3, q:"Who can be HARMED by international trade, according to the slides?", a:"Owners of resources used intensively in import-competing industries", w:["Consumers of imported goods","Exporters using abundant resources","Countries that specialize"], e:"Trade benefits countries as a whole but may harm particular groups."},
    {t:"Gains from trade", d:2, q:"True or false: Trade benefits countries as a whole but may harm particular groups within a country.", tf:true, e:"Both are true at once. That's why trade is politically contested."},
    {t:"Pattern of trade", d:1, q:"'Who sells what to whom' describes…", a:"The pattern of trade", w:["The gains from trade","The balance of payments","The gravity model"], e:"'The pattern of trade describes who sells what to whom.'"},
    {t:"Pattern of trade", d:2, q:"Case: A tropical country exports coffee and a desert country exports oil. The slides explain this pattern with differences in…", a:"Climate and resources", w:["Labor productivity only","Exchange rates","Trade agreements"], e:"Brazil–coffee and Saudi Arabia–oil are the slide examples."},
    {t:"Pattern of trade", d:3, q:"Case: Two countries with similar climates. One exports cars, the other exports aircraft. The slides explain this with differences in…", a:"Labor productivity and relative supplies of capital, labor and land", w:["Climate and natural resources","Currency values","Distance and borders"], e:"Climate explains coffee and oil. Cars vs aircraft needs productivity and factor supplies."},
    {t:"Trade policy", d:1, q:"Case: A government charges 20% on every imported phone. This policy is a…", a:"Tariff", w:["Quota","Export subsidy","Product specification"], e:"Tariff = a tax on imports or exports."},
    {t:"Trade policy", d:1, q:"Case: A government allows only a fixed amount of sugar to be imported each year. This policy is a…", a:"Quota", w:["Tariff","Export subsidy","Floating exchange rate"], e:"Quota = a quantity restriction on imports or exports."},
    {t:"Trade policy", d:1, q:"Case: A government pays domestic producers for every ton they sell abroad. This policy is an…", a:"Export subsidy", w:["Export tariff","Import quota","Official loan"], e:"Export subsidy = a payment to producers that export."},
    {t:"Trade policy", d:3, q:"Case: A rule requires all cars to meet a technical specification that only domestic cars meet. This trade barrier is…", a:"Another regulation that excludes foreign products", w:["A tariff","A quota","An export subsidy"], e:"'Other regulations (e.g., product specifications) that exclude foreign products from the market, but still allow domestic products.'"},
    {t:"Trade policy", d:2, q:"According to the slides, trade policies are often chosen to…", a:"Cater to special interest groups rather than maximize national welfare", w:["Maximize national welfare","Reduce government revenue","Lower consumer prices"], e:"A political-economy point from the trade policy slide."},
    {t:"Trade policy", d:2, q:"Case: A government adopts tariffs, then lowers them in exchange for other countries lowering theirs. This is…", a:"Negotiating trade barriers down reciprocally", w:["A trade deficit","An export subsidy","Service offshoring"], e:"'Governments tend to adopt tariffs, then negotiate them down in exchange for reduction in trade barriers of other countries.'"},
    {t:"International finance", d:2, q:"Case: Investors hold stocks and bonds from many countries so a bad year at home hurts less. This gain comes from…", a:"Diversification that reduces the variability of income", w:["Specialization in production","Higher tariffs","Export subsidies"], e:"Exchanging risky assets is another source of gains from trade."},
    {t:"International finance", d:1, q:"Case: A country imports more than it exports in value. This is a…", a:"Trade deficit", w:["Trade surplus","Balance of payments surplus","Quota"], e:"'Trade deficits, where countries import more than they export in value…'"},
    {t:"International finance", d:2, q:"A trade deficit may be offset by…", a:"Net inflows of financial assets", w:["Net outflows of financial assets","Higher tariffs","Export subsidies"], e:"Governments measure both goods flows and financial asset flows."},
    {t:"International finance", d:3, q:"The official settlements balance, or balance of payments, measures…", a:"The funds central banks use for official international payments", w:["Exports minus imports only","The value of a currency","Government spending on trade"], e:"Slide definition. Don't confuse it with the trade balance."},
    {t:"International finance", d:1, q:"How much domestic currency can be exchanged for foreign currency is the…", a:"Exchange rate", w:["Interest rate","Tariff rate","Balance of payments"], e:"Exchange rates affect how much imports cost at home and exports cost abroad."},
    {t:"International finance", d:1, q:"Case: A currency's value changes every day with the market. This exchange rate is…", a:"Floating", w:["Fixed","Pegged by treaty","Tariffed"], e:"'Some exchange rates change continually (float) while others are fixed for periods of time.'"},
    {t:"International finance", d:1, q:"Case: A central bank keeps its currency at the same rate for several years. This exchange rate is…", a:"Fixed", w:["Floating","Free","Black market"], e:"Fixed for periods of time."},
    {t:"International finance", d:2, q:"Exchange rate changes affect…", a:"The domestic cost of imports and the foreign cost of exports", w:["Only the volume of services","Only government spending","Nothing in trade"], e:"Goods priced in foreign currency (imports) and in domestic currency (exports) both change price."},
    {t:"International finance", d:2, q:"Why do countries in an integrated economy need some policy coordination?", a:"One country's economic policies usually affect other countries", w:["They all share one currency","Tariffs are illegal","Exchange rates never change"], e:"The need depends on the type of exchange rate regime."},
    {t:"International finance", d:2, q:"Arrangements where individuals and firms exchange money now for promises to pay in the future are…", a:"Capital markets", w:["Goods markets","Labor markets","Foreign exchange quotas"], e:"Slide definition."},
    {t:"International finance", d:2, q:"Case: A government cannot repay the bonds it sold to foreign investors. This risk is called…", a:"National default", w:["Currency appreciation","Diversification","A trade surplus"], e:"A special risk in international capital markets."},
    {t:"International finance", d:2, q:"Case: A foreign lender is repaid in a currency that lost value, so it gets back less. This risk is…", a:"Currency fluctuation", w:["National default","A tariff","A quota"], e:"Currency fluctuations can alter the value paid."},
    {t:"International finance", d:3, q:"Case: A firm raises money abroad to get around rules on its domestic market. International capital markets can offer…", a:"Opportunities to evade domestic regulations", w:["Protection from all risk","Guaranteed fixed exchange rates","Lower tariffs on goods"], e:"'Sometimes offer opportunities to evade regulations placed on domestic markets.'"},
    {t:"Gravity model", d:1, q:"The value of goods and services produced in an economy is its…", a:"Gross domestic product (GDP)", w:["Balance of payments","Trade balance","Capital stock"], e:"GDP measures economic size in the gravity model."},
    {t:"Gravity model", d:1, q:"The model that says trade between two countries is related to their economic size (and distance) is the…", a:"Gravity model", w:["Circular flow model","Ricardian model","Standard trade model"], e:"'Size Matters: The Gravity Model.'"},
    {t:"Gravity model", d:1, q:"In the gravity model, the size of an economy is ___ related to its volume of imports and exports.", a:"Directly", w:["Inversely","Not","Randomly"], e:"Bigger economies trade more."},
    {t:"Gravity model", d:2, q:"Why do larger economies EXPORT more, according to the gravity model?", a:"They produce more goods and services, so they have more to sell", w:["They have lower tariffs","They have fixed exchange rates","They are closer to everyone"], e:"Larger economies have more to sell in the export market."},
    {t:"Gravity model", d:2, q:"Why do larger economies IMPORT more, according to the gravity model?", a:"They generate more income, so they can buy more", w:["They produce less","They have higher tariffs","They use quotas less"], e:"'Larger economies generate more income … so they are able to buy more imports.'"},
    {t:"Gravity model", d:2, q:"Case: A country trades far more with a partner than the gravity model predicts. Economists call this…", a:"An anomaly", w:["A trade deficit","A quota","An export subsidy"], e:"'Using the Gravity Model: Looking for Anomalies.'"},
    {t:"Impediments", d:2, q:"Case: Two countries share a language and a history of migration, so they trade more than size predicts. This factor is…", a:"Cultural affinity", w:["Geography","Borders","Distance"], e:"Ireland is the slide example."},
    {t:"Impediments", d:2, q:"Case: Ocean harbors and no mountain barriers make shipping easy, so trade is higher. This factor is…", a:"Geography", w:["Cultural affinity","Multinational corporations","Borders"], e:"'Geography: ocean harbors and a lack of mountain barriers make transportation and trade easier.'"},
    {t:"Impediments", d:2, q:"Case: A company with divisions in several countries ships parts between its own branches. This factor that raises trade is…", a:"Multinational corporations", w:["Cultural affinity","Borders","Geography"], e:"Corporations spread across nations import and export between their divisions."},
    {t:"Impediments", d:2, q:"Case: Goods must clear customs, currencies must be exchanged and tariffs paid. This impediment to trade is…", a:"Borders", w:["Distance","Cultural affinity","Geography"], e:"Crossing borders involves formalities, time, currency exchange and tariffs."},
    {t:"Impediments", d:2, q:"Why does greater distance between markets reduce trade?", a:"It raises transportation costs", w:["It raises GDP","It lowers tariffs","It increases cultural affinity"], e:"Distance influences transportation costs and therefore the cost of imports and exports."},
    {t:"Impediments", d:3, q:"Case: Two countries trade more than their size predicts mainly because of their location near the partner's main routes. The slides call this…", a:"A transport cost advantage due to location", w:["Cultural affinity","A free trade agreement","A trade deficit"], e:"The Netherlands and Belgium are the slide examples."},
    {t:"Impediments", d:2, q:"The purpose of trade agreements between countries is to…", a:"Reduce border formalities and tariffs to increase trade", w:["Raise tariffs on neighbors","Fix exchange rates","Limit migration"], e:"Trade agreements reduce the cost of crossing borders."},
    {t:"Impediments", d:2, q:"Case: Neighbors sign an agreement that removes tariffs between them (like NAFTA or USMCA). This is a…", a:"Free trade agreement", w:["Quota agreement","Currency union","Export subsidy"], e:"NAFTA (later USMCA) is the slide example."},
    {t:"Impediments", d:3, q:"Case: Regions inside one country trade much more with each other than with equally distant regions across the border. This shows…", a:"The border effect: borders reduce trade even with a free trade agreement", w:["The gravity model is wrong","Distance does not matter","Cultural affinity is zero"], e:"Canadian provinces trade much more with each other than with U.S. states, even holding distance constant."},
    {t:"History of trade", d:2, q:"Why has the negative effect of distance on trade grown smaller over time?", a:"Modern transportation and communication", w:["Higher tariffs","More quotas","Fewer trade agreements"], e:"From 'Has the World Gotten Smaller?'"},
    {t:"History of trade", d:2, q:"The first wave of globalization relied on which technologies?", a:"Railroads, steamships and the telegraph", w:["Jets and the Internet","Containers and computers","Trucks and telephones"], e:"A global economy is not new. The first wave came before jets and the Internet."},
    {t:"History of trade", d:2, q:"Case: World trade collapses during world wars and a depression, then slowly recovers. What does this show?", a:"Political factors can change trade more than transport technology", w:["Technology alone decides trade","Distance no longer matters","Tariffs always fall over time"], e:"'Political factors, such as wars, can change trade patterns much more than innovations in transportation and communication.'"},
    {t:"History of trade", d:2, q:"Case: A product's parts cross borders several times before final assembly. This splitting of production into stages is called…", a:"Vertical disintegration of production", w:["Horizontal integration","Autarky","Import substitution"], e:"Extensive cross-shipping of components."},
    {t:"History of trade", d:3, q:"Why can vertical disintegration make trade flows worth MORE than the final product's value?", a:"Components are cross-shipped and counted each time they cross a border", w:["Prices rise at every border","Tariffs are added to GDP","Services are counted twice"], e:"A product can give rise to trade flows worth two or three times its value."},
    {t:"What we trade", d:2, q:"Today most world trade is in…", a:"Manufactured products", w:["Agricultural products","Fuels and mining products","Services"], e:"Manufactures dominate, though minerals like oil remain important."},
    {t:"What we trade", d:2, q:"Over time, exports of developing countries have shifted from ___ toward ___.", a:"Agricultural products; manufactured products", w:["Manufactures; agriculture","Services; minerals","Oil; agriculture"], e:"Figure 2.7: 'The Changing Composition of Developing-Country Exports.'"},
    {t:"Offshoring", d:1, q:"Case: A bank moves its customer call center to another country. This is…", a:"Service offshoring (outsourcing)", w:["Vertical disintegration","An export subsidy","A quota"], e:"A firm that provides services moves its operations to a foreign location."},
    {t:"Offshoring", d:2, q:"Which services can be offshored most easily?", a:"Services that can be transmitted electronically", w:["Services needing physical contact","Services run by the government","Services with high tariffs"], e:"Like call centers, whose calls travel electronically."},
    {t:"Offshoring", d:2, q:"Case: A haircut must be done close to the customer. This kind of job is…", a:"Nontradable", w:["Tradable","Offshorable","Interindustry"], e:"Most jobs need to be done close to the customer, making them nontradable."},
    {t:"Offshoring", d:2, q:"Case: Computer code can be written anywhere and sent over the internet. This kind of job is…", a:"Tradable", w:["Nontradable","Protected","Autarkic"], e:"Tradable jobs have the potential to be outsourced."},
    {t:"Offshoring", d:3, q:"True or false: Service outsourcing is currently a significant part of trade.", tf:false, e:"'Service outsourcing is currently not a significant part of trade.'"},
    {t:"Offshoring", d:2, q:"In modern trade, which resources matter MORE than natural resources?", a:"Human resources and human-created resources like machinery", w:["Gold and silver","Land and climate","Oil and minerals"], e:"From 'Do Old Rules Still Apply?'"},
    {t:"Offshoring", d:2, q:"Political battles over trade typically involve…", a:"Workers whose skills are made less valuable by imports", w:["Consumers who want lower prices","Exporters with abundant resources","Central banks"], e:"Clothing workers facing imported apparel, tech workers facing competition from abroad."},
    {t:"Offshoring", d:2, q:"True or false: Even though trade has changed, the fundamental principles discovered at the dawn of the global economy still apply.", tf:true, e:"Last content slide of Lecture 1."}
  ]
},
{
  id: 2, code: "L2", title: "Globalization",
  sub: "Markets vs production, drivers, institutions, open vs closed, the big debates",
  quip: "The world is interconnected. Your sleep schedule is not.",
  qs: [
    {t:"Definition", d:1, q:"The shift toward a more integrated and interdependent world economy is called…", a:"Globalization", w:["Autarky","Protectionism","Industrial policy"], e:"The world is moving away from self-contained national economies."},
    {t:"Definition", d:1, q:"What are the two facets of globalization?", a:"Globalization of markets and globalization of production", w:["Globalization of trade and finance","Imports and exports","FDI and portfolio investment"], e:"Two facets: markets and production."},
    {t:"Definition", d:2, q:"Merging historically separate national markets into one huge global marketplace is the…", a:"Globalization of markets", w:["Globalization of production","Vertical disintegration","Industrial policy"], e:"No longer a 'German market' or 'American market', just the global market."},
    {t:"Definition", d:2, q:"Case: A firm designs phones in one country, makes chips in another and assembles in a third. This is the…", a:"Globalization of production", w:["Globalization of markets","Autarky","Interindustry trade"], e:"Firms base each activity in its optimal location."},
    {t:"Definition", d:2, q:"Case: People around the world drink Coca-Cola, eat at McDonald's and listen to the same pop music. This shows…", a:"Consumer tastes converging on a global norm", w:["Falling transportation costs","Industrial policy","Rising trade barriers"], e:"One of the forces behind the globalization of markets."},
    {t:"Definition", d:2, q:"Case: A company sells the same basic product in every country. The slides say this…", a:"Helps create the global market", w:["Blocks globalization","Is a trade barrier","Is industrial policy"], e:"'Firms help create the global market by offering the same basic products worldwide.'"},
    {t:"Drivers", d:1, q:"Which two macro factors underlie the trend toward greater globalization?", a:"Declining trade and investment barriers, and technological change", w:["Rising tariffs and population growth","Colonialism and gold reserves","Wars and depressions"], e:"From 'Drivers of Globalization'."},
    {t:"Drivers", d:2, q:"Case: In the 1930s, countries raised tariffs against each other. These trade wars work against which driver of globalization?", a:"Declining trade barriers", w:["Technological change","Converging tastes","Global institutions"], e:"Lifting barriers to trade drives globalization; trade wars do the opposite."},
    {t:"Drivers", d:1, q:"Case: A firm sells its products to consumers in another country. This is…", a:"International trade", w:["Foreign direct investment","Portfolio investment","Offshoring"], e:"International trade occurs when a firm exports goods or services to consumers in another country."},
    {t:"Drivers", d:1, q:"Case: A firm invests resources in business activities outside its home country. This is…", a:"Foreign direct investment (FDI)", w:["International trade","An export subsidy","A tariff"], e:"Definition from the Globalization lecture."},
    {t:"Drivers", d:2, q:"Lower barriers to trade and investment mean firms can…", a:"See the world as their market and base production in the optimal location", w:["Only sell at home","Ignore competition","Avoid all regulation"], e:"The world, not a single country, becomes the market."},
    {t:"Drivers", d:2, q:"Microprocessors, telecommunications, the Internet and better transportation are examples of which driver of globalization?", a:"Technological change", w:["Declining trade barriers","Converging tastes","Global institutions"], e:"'Technological change has made the globalization of markets a reality.'"},
    {t:"Drivers", d:2, q:"Case: Cheaper shipping lets a firm put factories in distant, low-cost locations. This is an implication of…", a:"Lower transportation costs", w:["Higher tariffs","Lower information costs","Fixed exchange rates"], e:"Lower transport costs let firms disperse production to economical, geographically separate locations."},
    {t:"Drivers", d:2, q:"Case: Cheap internet and computing let headquarters manage plants on three continents. This is an implication of…", a:"Lower information processing and communication costs", w:["Lower transportation costs","Declining tariffs","Converging tastes"], e:"They let firms create and manage globally dispersed production systems."},
    {t:"Institutions", d:2, q:"The institution established to maintain order in the international monetary system is the…", a:"International Monetary Fund (IMF)", w:["World Bank","World Trade Organization","United Nations"], e:"IMF = monetary order. World Bank = economic development."},
    {t:"Institutions", d:2, q:"The institution established to promote economic development is the…", a:"World Bank", w:["IMF","WTO","GATT"], e:"From 'The Emergence of Global Institutions'."},
    {t:"Institutions", d:3, q:"True or false: The World Bank was established to maintain order in the international monetary system.", tf:false, e:"That's the IMF. The World Bank promotes economic development."},
    {t:"Institutions", d:2, q:"The institution that polices the world trading system and makes sure countries follow trade treaty rules is the…", a:"World Trade Organization (WTO)", w:["IMF","World Bank","United Nations"], e:"It also promotes lower barriers to trade and investment."},
    {t:"Institutions", d:1, q:"The predecessor of the WTO was…", a:"GATT (General Agreement on Tariffs and Trade)", w:["The IMF","The World Bank","NAFTA"], e:"GATT → WTO."},
    {t:"Institutions", d:2, q:"Case: A country facing a currency crisis asks for help restoring monetary order. Which institution fits?", a:"IMF", w:["World Bank","WTO","GATT"], e:"Monetary order = IMF."},
    {t:"Institutions", d:2, q:"Case: A country gets a loan to build roads and schools to promote development. Which institution fits?", a:"World Bank", w:["IMF","WTO","GATT"], e:"Development = World Bank."},
    {t:"Institutions", d:2, q:"Case: A country breaks the rules of a trade treaty it signed. Which institution handles this?", a:"WTO", w:["IMF","World Bank","United Nations"], e:"The WTO polices the world trading system."},
    {t:"Measurement", d:2, q:"How do the slides measure the degree of globalization in TRADE?", a:"Trade volume divided by GDP", w:["Exports minus imports","Number of trade agreements","Average tariff rate"], e:"Trade volume ($) / GDP ($)."},
    {t:"Measurement", d:2, q:"How do the slides measure the degree of globalization in CAPITAL?", a:"Capital flows (such as FDI) divided by GDP", w:["Tariffs divided by GDP","Population divided by GDP","Exports divided by imports"], e:"Capital flows ($) / GDP ($)."},
    {t:"Measurement", d:3, q:"Case: A small trading hub's total trade is several times larger than its GDP. This indicates…", a:"A very high degree of trade globalization (openness)", w:["A closed economy","A trade deficit","Autarky"], e:"Trade/GDP above 100% is possible for trading hubs."},
    {t:"Measurement", d:3, q:"Foreign capital STOCKS / GDP measures accumulated foreign capital at a point in time, as opposed to…", a:"Capital flows during a period", w:["Trade volume","Tariff revenue","Exchange rates"], e:"The slide stresses: stocks, not flows."},
    {t:"Measurement", d:3, q:"True or false: The world was more open in the late 19th century than right after World War II.", tf:true, e:"Wars and protectionism reversed the first wave of globalization."},
    {t:"Measurement", d:2, q:"Trade patterns have shifted from agricultural to manufactured products. What do the slides suggest as the next stage?", a:"Services", w:["Agriculture again","Gold and silver","Raw minerals"], e:"'The Next Stage? Services?'"},
    {t:"Open vs closed", d:2, q:"The Sachs & Warner classification decides whether a country is open based on…", a:"Its policies, not outcomes like trade levels", w:["Its trade volume / GDP","Its GDP per capita","Its population"], e:"A policy-based indicator of globalization."},
    {t:"Open vs closed", d:3, q:"How many Sachs & Warner criteria must a country fail to be classified as CLOSED?", a:"Just one", w:["At least three","All five","At least two"], e:"'If any of these 5 criteria is not met, the country is classified as closed.'"},
    {t:"Open vs closed", d:2, q:"Which of these is one of the Sachs & Warner criteria for being open?", a:"No state monopoly on major exports", w:["A trade surplus","WTO membership","Fast GDP growth"], e:"Others: low tariffs, low non-tariff barriers, low black market premium, no socialist system."},
    {t:"Open vs closed", d:3, q:"Case: A country has low tariffs and few non-tariff barriers, but a large black market exchange rate premium. Sachs & Warner classify it as…", a:"Closed", w:["Open","Partly open","Not classified"], e:"Failing any single criterion makes a country closed."},
    {t:"Open vs closed", d:3, q:"Case: A country has low tariffs but a socialist system where the communist party keeps undivided power. Sachs & Warner classify it as…", a:"Closed", w:["Open","Open, because tariffs are low","Not classified"], e:"No socialist economic system is one of the five criteria."},
    {t:"Open vs closed", d:2, q:"Case: A country meets all five Sachs & Warner criteria. It is classified as…", a:"Open", w:["Closed","Partly closed","Socialist"], e:"All criteria met = open."},
    {t:"Open vs closed", d:2, q:"Trade restrictions other than tariffs, such as quotas, are called…", a:"Non-tariff barriers", w:["Export subsidies","Capital flows","Black market premiums"], e:"One Sachs & Warner criterion limits how much trade they cover."},
    {t:"Open vs closed", d:3, q:"Sachs & Warner treat a large gap between the official and black market exchange rate as a sign of…", a:"A closed economy", w:["An open economy","A trade surplus","Technological change"], e:"A high black market premium fails the criterion. China in 2000 is the slide example."},
    {t:"Open vs closed", d:3, q:"Case: A country has very high average tariffs and non-tariff barriers covering most of its trade. Sachs & Warner classify it as…", a:"Closed", w:["Open","Open, if it has no state monopolies","Not classified"], e:"India in 2000 is the slide example."},
    {t:"Open vs closed", d:2, q:"A rising share of countries classified as 'open' over time is evidence of…", a:"Increased globalization", w:["Rising protectionism","Autarky","Falling trade"], e:"'Another indication of increased globalization.'"},
    {t:"Debates", d:2, q:"Dollar and Kraay (World Bank) argued that the recent wave of globalization has…", a:"Promoted economic equality and reduced poverty", w:["Dramatically increased inequality","Had no effect on poverty","Destroyed jobs everywhere"], e:"The opposing quote is from a U.S. union leader, Jay Mazur."},
    {t:"Debates", d:2, q:"Jay Mazur, a U.S. union leader, claimed globalization has…", a:"Dramatically increased inequality between and within nations", w:["Reduced poverty sharply","Promoted equality","Had no effect on wages"], e:"The anti-globalization side of the debate."},
    {t:"Debates", d:2, q:"Case: The gap between rich nations and poor nations. This is…", a:"Between-country inequality", w:["Within-country inequality","Net job creation","A trade deficit"], e:"Compare averages across countries."},
    {t:"Debates", d:2, q:"Case: The gap between rich and poor citizens inside one nation. This is…", a:"Within-country inequality", w:["Between-country inequality","Gross job destruction","Capital flight"], e:"Compare people within one country."},
    {t:"Debates", d:3, q:"According to the pro-globalization view, globalization has reduced…", a:"Between-country inequality", w:["Within-country inequality","All inequality everywhere","Nothing"], e:"And there's no evidence of a significant impact on within-country inequality."},
    {t:"Debates", d:3, q:"Anti-globalization voices mostly emphasize…", a:"Within-country inequality", w:["Between-country inequality","GDP growth","Tariff levels"], e:"'They emphasize mostly on within-country inequality, not between-country one.'"},
    {t:"Debates", d:2, q:"The pro-globalization side says globalization raises a country's income by…", a:"Specialization in its strength, more capital flows and technology transfer", w:["Raising tariffs","Creating state monopolies","Reducing exports"], e:"From 'Embrace the idea of globalization'."},
    {t:"Debates", d:2, q:"The pro-globalization side says raising the level of income ___ the distribution of income.", a:"Does not affect", w:["Worsens","Always equalizes","Destroys"], e:"Slide title: 'raising the level of income does not affect the distribution of income.'"},
    {t:"Debates", d:3, q:"Critics argue that the World Bank's $1-a-day poverty line is…", a:"Arbitrary", w:["Too generous","Perfectly accurate","Set by the WTO"], e:"'The 1-dollar threshold set by the World Bank is totally arbitrary.'"},
    {t:"Debates", d:1, q:"Case: A U.S. firm closes a factory at home and moves the jobs abroad. This is…", a:"Offshoring", w:["Insourcing","Import substitution","Autarky"], e:"The slides discuss jobs lost to offshoring."},
    {t:"Debates", d:2, q:"Case: Workers accept lower wages because their employer could move production abroad. This channel is…", a:"The mere threat of foreign competition", w:["Technology transfer","Net job creation","A quota"], e:"Listed under 'Trade and Wages'."},
    {t:"Debates", d:2, q:"Case: Firms invest heavily in factories abroad instead of at home. The slides say this means…", a:"Lower investment in the domestic manufacturing base", w:["More domestic investment","Lower imports","Higher tariffs"], e:"And greater foreign capacity to compete directly with domestic manufacturers."},
    {t:"Debates", d:3, q:"Globalization creates worker insecurity partly because it increases firms'…", a:"Price elasticity of demand for labor", w:["Fixed costs","Tariff revenue","Exchange rate premium"], e:"Cheaper foreign labor can substitute for domestic labor."},
    {t:"Debates", d:3, q:"Case: A firm can easily swap domestic workers for foreign ones. What happens to domestic wages and jobs?", a:"They become more volatile", w:["They become more stable","They always rise","Nothing changes"], e:"Higher labor demand elasticity raises the volatility of wages and employment."},
    {t:"Debates", d:2, q:"Which is NOT listed as an effect of greater worker insecurity?", a:"Higher consumer spending", w:["Wage restraint","Ill health","Economic inequality"], e:"The slide lists a REDUCTION in consumer spending."},
    {t:"Debates", d:2, q:"Case: Count only the jobs lost when a plant moves abroad, ignoring jobs created elsewhere. This measures…", a:"Gross job destruction", w:["Net job creation","Within-country inequality","Capital flows"], e:"The anti-globalization side likes to use these specific cases."},
    {t:"Debates", d:2, q:"Case: Jobs created minus jobs lost across the whole economy. This measures…", a:"Net job creation", w:["Gross job destruction","Offshoring","The trade balance"], e:"The pro-globalization side focuses on this."},
    {t:"Debates", d:3, q:"Case: A multinational opens a plant abroad and its parent company then hires MORE workers at home. Foreign activity ___ domestic activity.", a:"Complements", w:["Substitutes for","Destroys","Has no link to"], e:"Economists found foreign activity by U.S. multinationals complements domestic activity."},
    {t:"Debates", d:3, q:"A study shows low-skilled workers lose jobs in the short run after outsourcing. What does it NOT show?", a:"Long-run structural job destruction", w:["Short-run job losses","That some workers are hurt","Any effect on low-skilled workers"], e:"From the Hong Kong labor market study."},
    {t:"Debates", d:2, q:"True or false: Activities linked to outsourcing are very large and have increased sharply in recent years.", tf:false, e:"They are 'neither quantitatively large nor have they increased markedly.'"},
    {t:"Debates", d:2, q:"Within-country inequality rose while globalization increased. What do the slides conclude about the link?", a:"They are not shown to be related, but people blame globalization anyway", w:["Globalization clearly caused it","Inequality caused globalization","Both fell together"], e:"'But are they related? The short answer is no, as we have seen. But people blame their misfortunes on it anyway.'"},
    {t:"Debates", d:2, q:"Spillover effects to other sectors and imports of intermediate goods are channels through which trade affects…", a:"Domestic wages", w:["Exchange rate regimes","Tariff schedules","The IMF"], e:"Both are listed under 'Trade and Wages'."}
  ]
},
{
  id: 3, code: "L3", title: "Free Trade",
  sub: "Foundation of modern trade theory, economies of scale, mercantilism, absolute advantage",
  quip: "Adam Smith said trade is positive-sum. Your GPA said otherwise.",
  qs: [
    {t:"Globalization recap", d:1, q:"Which two factors underlie globalization (Lecture 3 recap)?", a:"Decline in barriers and technological change", w:["Colonialism and gold","Wars and depressions","Tariffs and quotas"], e:"'Technological change: knowledge is imported and exported.'"},
    {t:"Globalization recap", d:2, q:"Case: Countries produce the goods and services they make most efficiently and trade for the rest. This is…", a:"Specialization", w:["Autarky","Mercantilism","Protectionism"], e:"The benefit side of the 'However…' slide."},
    {t:"Globalization recap", d:2, q:"Which criticism of trade appears on the 'However…' slide?", a:"It destroys manufacturing jobs in wealthy nations", w:["It reduces product variety","It slows technology","It raises transport costs"], e:"Critics also say companies move to countries with fewer regulations."},
    {t:"Globalization recap", d:2, q:"Case: A company moves its factory to a country with weaker labor and environmental rules. This is a criticism that firms…", a:"Relocate to places with fewer labor and environmental regulations", w:["Gain economies of scale","Specialize by comparative advantage","Reduce imports"], e:"From the 'However…' slide."},
    {t:"Economies of scale", d:2, q:"The standard trade model by Paul Krugman says trade lets countries benefit from…", a:"Larger economies of scale", w:["Colonial treasure","Higher tariffs","Fixed exchange rates"], e:"A bigger market means bigger scale."},
    {t:"Economies of scale", d:1, q:"The lowering of per-unit costs as a firm grows bigger is called…", a:"Economies of scale", w:["Diseconomies of scale","Opportunity cost","Absolute advantage"], e:"Exact slide definition."},
    {t:"Economies of scale", d:1, q:"Case: A baker pays the same daily rent whether baking 100 or 200 breads. Rent is a…", a:"Fixed cost", w:["Variable cost","Opportunity cost","Per-unit cost"], e:"Fixed costs don't change with output."},
    {t:"Economies of scale", d:1, q:"Case: The baker spends more on flour for every extra bread. Flour is a…", a:"Variable cost", w:["Fixed cost","Sunk cost","Opportunity cost"], e:"Variable costs rise with each unit produced."},
    {t:"Economies of scale", d:1, q:"A cost that does NOT change with the amount produced is a…", a:"Fixed cost", w:["Variable cost","Marginal revenue","Profit"], e:"Like the bakery's rent."},
    {t:"Economies of scale", d:1, q:"A cost that changes with the amount produced is a…", a:"Variable cost", w:["Fixed cost","Profit","Tariff"], e:"Like the bakery's flour."},
    {t:"Economies of scale", d:2, q:"Total cost divided by the number of units produced is the…", a:"Per-unit (average) cost", w:["Fixed cost","Profit","Price"], e:"Economies of scale = falling per-unit cost."},
    {t:"Economies of scale", d:2, q:"Revenue minus costs is…", a:"Profit", w:["Variable cost","Per-unit cost","Opportunity cost"], e:"In the bakery: revenue minus rent minus flour."},
    {t:"Economies of scale", d:2, q:"Case: The baker doubles output and the cost per bread falls. This is an example of…", a:"Economies of scale", w:["Opportunity cost","Absolute advantage","Autarky"], e:"Per-unit cost falls as the firm grows."},
    {t:"Economies of scale", d:3, q:"In the bakery example, WHY does the cost per bread fall as output rises?", a:"The fixed rent is spread over more breads", w:["Flour gets cheaper per bread","The price rises","Rent falls when output rises"], e:"The same rent divided by more units."},
    {t:"Economies of scale", d:3, q:"Case: The baker's output doubles but profit more than doubles. The reason is…", a:"Fixed costs are spread over more units", w:["Variable costs disappear","The price doubles","Demand falls"], e:"Rent stays the same while revenue keeps growing."},
    {t:"Economies of scale", d:2, q:"How does trade connect to economies of scale?", a:"A larger market lets firms produce more and lower per-unit costs", w:["Trade raises fixed costs","Trade makes firms smaller","Trade removes variable costs"], e:"That's the core of Krugman's standard trade model."},
    {t:"Mercantilism", d:2, q:"The 16th–18th century belief that a nation's wealth depends on accumulated treasure is…", a:"Mercantilism", w:["Absolute advantage","Free trade","Comparative advantage"], e:"Gold and silver were the currency of trade."},
    {t:"Mercantilism", d:2, q:"Under the accumulated-treasure view, the main way to increase a country's wealth was…", a:"Colonialism", w:["Free trade agreements","Specialization","Foreign direct investment"], e:"'The stronger, the wealthier.'"},
    {t:"Mercantilism", d:1, q:"Under the accumulated-treasure view, trading was seen as…", a:"Losing", w:["Winning for both sides","A positive-sum game","Necessary for growth"], e:"'So, trading is losing!'"},
    {t:"Mercantilism", d:2, q:"Case: A nation hoards gold and silver and tries to limit what it buys from others. Which view of wealth is this?", a:"Mercantilism (accumulated treasure)", w:["Absolute advantage","Comparative advantage","Economies of scale"], e:"Wealth = treasure, so trade is seen as losing."},
    {t:"Mercantilism", d:3, q:"True or false: Adam Smith argued that a nation's wealth depends on its accumulated gold and silver.", tf:false, e:"That was the earlier belief Smith attacked."},
    {t:"Mercantilism", d:3, q:"Case: A country with almost no natural resources becomes one of the richest per person. What does this suggest?", a:"Wealth does not come only from natural resources or treasure", w:["Natural resources decide wealth","Colonialism is the only path to wealth","Trade makes countries poorer"], e:"The slide table: Singapore has no listed resources but very high GDP per capita."},
    {t:"Mercantilism", d:2, q:"Which slogan sums up the colonial-era view of wealth on the slides?", a:"The stronger, the wealthier", w:["Trade makes everyone richer","Specialize and trade","Size matters"], e:"Colonialism was the means of increasing wealth."},
    {t:"Absolute advantage", d:1, q:"Case: One nation's gain from trade is exactly the other nation's loss. This is a…", a:"Zero-sum game", w:["Positive-sum game","Comparative advantage","Economy of scale"], e:"Smith proved this belief wrong."},
    {t:"Absolute advantage", d:1, q:"Case: Both nations end up better off from voluntary exchange. This is a…", a:"Positive-sum game", w:["Zero-sum game","Negative-sum game","Mercantilist game"], e:"Smith: voluntary exchange (trade) is a positive-sum game."},
    {t:"Absolute advantage", d:1, q:"The ability of a country to produce more of a product with the same amount of input than another country is…", a:"Absolute advantage", w:["Comparative advantage","Opportunity cost","Economies of scale"], e:"Lower opportunity cost = COMPARATIVE advantage. Don't mix them up."},
    {t:"Absolute advantage", d:2, q:"According to absolute advantage theory, a country should…", a:"Produce only goods where it is most efficient and trade for the rest", w:["Produce everything itself","Import everything","Produce goods with the highest price"], e:"Smith's rule from the slides."},
    {t:"Absolute advantage", d:1, q:"Who developed the theory of absolute advantage?", a:"Adam Smith", w:["David Ricardo","Paul Krugman","Sachs & Warner"], e:"Absolute = Smith. Comparative = Ricardo."},
    {t:"Absolute advantage", d:2, q:"Smith proved wrong the belief that trade was…", a:"A zero-sum game", w:["A positive-sum game","Good for both nations","Based on specialization"], e:"Trade is positive-sum: both nations can gain."},
    {t:"Absolute advantage", d:2, q:"The tables show the output of ONE person per day. This measure is…", a:"Labor productivity", w:["Opportunity cost","GDP per capita","Relative price"], e:"Absolute advantage compares labor productivity."},
    {t:"Models", d:1, q:"Why do economists use assumptions?", a:"To simplify the complex world and make it easier to understand", w:["To make models perfectly realistic","To predict exact prices","To avoid using data"], e:"E.g. two countries and two goods."},
    {t:"Models", d:1, q:"A highly simplified representation of a more complicated reality is a…", a:"Model", w:["Assumption","Policy","Theory of value"], e:"Slide definition."},
    {t:"Models", d:2, q:"Which model is shown on the slides as an example of an economic model?", a:"The circular flow of income", w:["The gravity model","The Phillips curve","The IS-LM model"], e:"'Circular Flow of Income Model.'"},
    {t:"Models", d:2, q:"True or false: Assuming only two countries and two goods is unrealistic, so it gives no useful insights.", tf:false, e:"'Unrealistic, but simple to learn and gives useful insights about the real world.'"},
    {t:"Models", d:2, q:"Case: To study trade, we assume just two countries and two goods. This is an example of…", a:"A simplifying assumption", w:["A real-world fact","A trade policy","A market failure"], e:"Assumptions simplify the complex world."},
    {t:"Shoes & cloth", d:1, q:"A country that produces and consumes only its own output, with no trade, is in…", a:"Autarky", w:["Free trade","Specialization","A customs union"], e:"Autarky = no trade."},
    {t:"Shoes & cloth", d:1, q:"Case: One worker per day makes 1 shoe or 8 yards of cloth in Uzbekistan, and 2.5 shoes or 5 yards in China. Uzbekistan has an…", a:"Absolute advantage in cloth", w:["Absolute advantage in shoes","Absolute advantage in both","Absolute advantage in neither"], e:"Uzbek workers are more productive in cloth."},
    {t:"Shoes & cloth", d:1, q:"Same case. China has an…", a:"Absolute advantage in shoes", w:["Absolute advantage in cloth","Absolute advantage in both","Absolute advantage in neither"], e:"Chinese workers are more productive in shoes."},
    {t:"Shoes & cloth", d:1, q:"Following Smith in the shoes and cloth case, Uzbekistan should specialize in ___ and China in ___.", a:"Cloth; shoes", w:["Shoes; cloth","Both goods; nothing","Nothing; both goods"], e:"Each specializes where it is most efficient."},
    {t:"Shoes & cloth", d:2, q:"After specializing, which good does Uzbekistan EXPORT?", a:"Cloth", w:["Shoes","Both goods","Neither good"], e:"It exports its absolute-advantage good and imports shoes."},
    {t:"Shoes & cloth", d:2, q:"The total production of all countries combined is…", a:"World output", w:["GDP per capita","Autarky output","Net exports"], e:"Compared under autarky vs specialization."},
    {t:"Shoes & cloth", d:2, q:"Case: After each country specializes, total production of both goods rises. This gain comes from…", a:"Specialization", w:["Autarky","Tariffs","Colonialism"], e:"World output rises when each country makes what it's best at."},
    {t:"Shoes & cloth", d:2, q:"Case: After trade, each country consumes more than it did in autarky. This is…", a:"Gains from trade", w:["A zero-sum game","Mercantilism","A trade deficit"], e:"Both countries end up better off."},
    {t:"Shoes & cloth", d:3, q:"True or false: Trade itself increases world output compared to specialization alone.", tf:false, e:"Specialization raises world output. Trade redistributes that same output so both can consume both goods."},
    {t:"Shoes & cloth", d:3, q:"After countries specialize, what job does trade do?", a:"It lets each country consume both goods", w:["It raises total world output again","It returns countries to autarky","It removes absolute advantage"], e:"World output is the same with specialization alone and with specialization plus trade."},
    {t:"Shoes & cloth", d:2, q:"In these examples, how are the gains from trade shown?", a:"Each country consumes more than its autarky levels", w:["Each country hoards more gold","Prices rise in both countries","Tariffs fall to zero"], e:"Compare consumption after trade with autarky."},
    {t:"Computers & bicycles", d:1, q:"Case: India makes 5 computers or 5 bicycles; Pakistan makes 3 computers or 8 bicycles. India has an…", a:"Absolute advantage in computers", w:["Absolute advantage in bicycles","Absolute advantage in both","Absolute advantage in neither"], e:"India makes more computers."},
    {t:"Computers & bicycles", d:1, q:"Same case. Pakistan has an…", a:"Absolute advantage in bicycles", w:["Absolute advantage in computers","Absolute advantage in both","Absolute advantage in neither"], e:"Pakistan makes more bicycles."},
    {t:"Computers & bicycles", d:2, q:"In the India–Pakistan case, which good does India export after specializing?", a:"Computers", w:["Bicycles","Both goods","Neither good"], e:"India trades computers for bicycles."},
    {t:"Computers & bicycles", d:2, q:"Case: After specialization and trade, both India and Pakistan consume more of both goods than in autarky. This makes trade a…", a:"Positive-sum game", w:["Zero-sum game","Mercantilist policy","Trade deficit"], e:"Both countries gain."},
    {t:"Computers & bicycles", d:3, q:"True or false: In the India–Pakistan case, world output is the same with specialization alone and with specialization plus trade.", tf:true, e:"Trade only changes who consumes what."},
    {t:"Both goods", d:2, q:"Case: China produces more shoes AND more cloth per worker than Uzbekistan. China has…", a:"An absolute advantage in both goods", w:["An absolute advantage in shoes only","A comparative advantage in both goods","No advantage at all"], e:"China is better at both."},
    {t:"Both goods", d:3, q:"If one country has an absolute advantage in BOTH goods, is there no reason for it to trade?", a:"No, trade can still help both countries", w:["Correct, it should not trade","Only the weaker country should stop trading","Trade only helps the stronger country"], e:"'It is not RIGHT! How come?' Comparative advantage explains it."},
    {t:"Both goods", d:2, q:"Which theory explains why trade still pays when one country is better at everything?", a:"Comparative advantage", w:["Absolute advantage","Mercantilism","Economies of scale"], e:"Ricardo's theory, Lecture 4."},
    {t:"Both goods", d:3, q:"True or false: Under absolute advantage theory alone, a country that is better at everything has no reason to trade.", tf:true, e:"That's the gap comparative advantage fills."},
    {t:"Absolute advantage", d:2, q:"Case: Two countries trade voluntarily and both gain. Which belief does this disprove?", a:"That trade is a zero-sum game", w:["That trade has gains","That specialization works","That productivity matters"], e:"Smith's key argument."},
    {t:"Absolute advantage", d:2, q:"Trade between countries is beneficial under absolute advantage theory because…", a:"Each country produces what it is most efficient at, so total output rises", w:["Countries collect more gold","Tariffs rise","Each country produces everything"], e:"'Trade between countries is, therefore, beneficial.'"},
    {t:"Economies of scale", d:2, q:"Case: A firm's costs per unit fall as it grows because fixed costs are shared across more output. Which trade theory builds on this idea?", a:"Krugman's standard trade model", w:["Smith's absolute advantage","Mercantilism","The gravity model"], e:"Trade lets countries benefit from larger economies of scale."},
    {t:"Mercantilism", d:2, q:"Gold and silver serving as the currency of trade is a feature of…", a:"The mercantilist era", w:["Absolute advantage theory","Krugman's model","Comparative advantage"], e:"16th–18th centuries."},
    {t:"Absolute advantage", d:3, q:"Case: Country A makes more of a good than Country B using the same inputs. Which concept is this?", a:"Absolute advantage", w:["Comparative advantage","Opportunity cost","Economies of scale"], e:"Same inputs, more output = absolute advantage."},
    {t:"Shoes & cloth", d:2, q:"Case: Uzbekistan specializes in cloth and wants shoes. What should it do?", a:"Trade cloth for shoes with China", w:["Produce shoes itself","Stop consuming shoes","Return to autarky"], e:"Specialize, then trade."}
  ]
},
{
  id: 4, code: "L4", title: "Comparative Advantage",
  sub: "Ricardo, opportunity cost, PPFs, relative prices, factor endowments",
  quip: "Bill Gates shouldn't cook. You shouldn't skip this lecture.",
  qs: [
    {t:"Ricardo", d:1, q:"Who developed comparative advantage theory?", a:"David Ricardo", w:["Adam Smith","Paul Krugman","Jeffrey Sachs"], e:"David Ricardo, Principles of Political Economy."},
    {t:"Ricardo", d:2, q:"Ricardo argued a country should import or trade even if…", a:"It is more efficient in producing the product than the other country", w:["It has no natural resources","Its tariffs are high","It is in autarky"], e:"The key difference from Smith's absolute advantage."},
    {t:"Ricardo", d:1, q:"Producing a good at a lower opportunity cost than other countries is…", a:"Comparative advantage", w:["Absolute advantage","Economies of scale","Autarky"], e:"More output per input = absolute. Lower opportunity cost = comparative."},
    {t:"Ricardo", d:3, q:"True or false: Comparative advantage means producing more of a good with the same inputs than another country.", tf:false, e:"That's absolute advantage. Comparative = lower opportunity cost."},
    {t:"Ricardo", d:3, q:"Which kind of advantage is NECESSARY for gains from trade?", a:"Comparative advantage", w:["Absolute advantage","Absolute advantage in both goods","Neither"], e:"Even a country with no absolute advantage has a comparative advantage in something."},
    {t:"Opportunity cost", d:1, q:"The value of the next best alternative you give up is the…", a:"Opportunity cost", w:["Money price","Fixed cost","Relative price"], e:"Every choice has an opportunity cost."},
    {t:"Opportunity cost", d:1, q:"Case: Buying a burger means giving up four bus tickets. The four bus tickets are the burger's…", a:"Opportunity cost", w:["Variable cost","Absolute advantage","Relative price in money"], e:"The slide's burger example."},
    {t:"Opportunity cost", d:2, q:"Case: Your cousin buys a bicycle for $300. The $300 measures…", a:"The other consumption he gave up", w:["Only the bike's production cost","His lost earnings","The bike's resale value"], e:"Here the money price is a fair measure of opportunity cost."},
    {t:"Opportunity cost", d:2, q:"Case: Going to college means paying tuition AND not working during class hours. The full cost is…", a:"Out-of-pocket costs plus the opportunity cost of lost earnings", w:["Only tuition","Only books and housing","Nothing if you get a scholarship"], e:"College imposes both an out-of-pocket cost and an opportunity cost."},
    {t:"Opportunity cost", d:2, q:"True or false: The price in dollars always captures the true opportunity cost.", tf:false, e:"Not when the cost of time is involved."},
    {t:"Opportunity cost", d:1, q:"A fundamental principle of economics on the slides is that…", a:"Every choice has an opportunity cost", w:["Trade is zero-sum","Prices always equal costs","Free goods exist"], e:"Straight from the slide."},
    {t:"Gates vs Cook", d:2, q:"Case: Bill Gates spends an hour cooking his lunch. His opportunity cost is…", a:"The programming income he gives up in that hour", w:["The price of the groceries","One meal","Nothing, he's a great cook"], e:"His hour of programming is worth a huge amount."},
    {t:"Gates vs Cook", d:2, q:"Case: Mr. Cook spends an hour programming. His opportunity cost is…", a:"What he would have earned in that hour", w:["Bill Gates' hourly income","Nothing","The price of a computer"], e:"His next best alternative is much less valuable than Gates'."},
    {t:"Gates vs Cook", d:2, q:"Bill Gates is better than anyone at both cooking and programming. He has an ___ in both.", a:"Absolute advantage", w:["Comparative advantage","Opportunity cost","Autarky"], e:"Better at both = absolute advantage in both."},
    {t:"Gates vs Cook", d:2, q:"Bill Gates has a COMPARATIVE advantage in…", a:"Programming", w:["Cooking","Both","Neither"], e:"His opportunity cost of cooking is enormous."},
    {t:"Gates vs Cook", d:2, q:"Mr. Cook should specialize in…", a:"Cooking", w:["Programming","Both equally","Neither"], e:"He has the lower opportunity cost of cooking."},
    {t:"Gates vs Cook", d:3, q:"The slides describe comparative advantage as…", a:"'More absolute advantage' in one activity than in the other", w:["Absolute advantage in everything","The highest wage","The lowest money price"], e:"'He has comparative advantage (= more absolute advantage) in programming than cooking.'"},
    {t:"Gates vs Cook", d:2, q:"The lower your opportunity cost of an activity…", a:"The more comparative advantage you have in it", w:["The less you should do it","The higher its price","The more absolute advantage you lose"], e:"'The lesser OC of X activity, the comparative advantage you have in it.'"},
    {t:"Gates vs Cook", d:3, q:"True or false: Because Bill Gates is the best cook in town, he should cook for himself.", tf:false, e:"He's better off programming and trading with someone who has a lower opportunity cost of cooking."},
    {t:"Gates vs Cook", d:3, q:"Case: Country A is better than B at both wine and cloth, but its lead is much bigger in wine. A has a comparative advantage in…", a:"Wine", w:["Cloth","Both","Neither"], e:"Comparative advantage = where your advantage is greatest (lowest opportunity cost)."},
    {t:"Gates vs Cook", d:2, q:"Case: Country A gives up less cloth to make one unit of wine than Country B does. A has…", a:"A comparative advantage in wine", w:["An absolute advantage in cloth","A comparative advantage in cloth","No advantage"], e:"Lower opportunity cost = comparative advantage."},
    {t:"Why trade", d:2, q:"Case: We can produce the same goods, but production is fixed and I like oranges while you like apples. Will we trade?", a:"Yes, because tastes differ", w:["No, never","Only with tariffs","Only if prices are equal"], e:"Case 1: production fixed, tastes differ = trade."},
    {t:"Why trade", d:3, q:"Case: Same production ability, different tastes, but each of us can produce ANY combination we want. Will we trade?", a:"No, each produces what it wants to consume", w:["Yes, always","Only for oranges","Only at free trade prices"], e:"'If free to produce whatever we want … then no trade even if tastes differ.'"},
    {t:"Why trade", d:2, q:"Why are production capabilities often NOT the same across countries?", a:"Some production is fixed by soil, natural resources, oil and minerals", w:["Tastes are the same everywhere","Tariffs are zero","Everyone has the same technology"], e:"That restriction on production creates reasons to trade."},
    {t:"Why trade", d:2, q:"Case: Two countries have the same tastes but different technology. Will they trade?", a:"Yes, through absolute and comparative advantage", w:["No","Only if tastes differ","Only with export subsidies"], e:"Case 3 on 'The Advantages of Trade' slide."},
    {t:"Why trade", d:3, q:"Case: Two countries have the same technology and same tastes, but one has lots of capital and the other lots of labor. Will they trade?", a:"Yes, because of different factor endowments", w:["No, nothing differs that matters","Only if tariffs are zero","Only in services"], e:"Case 4: different endowments still create comparative advantage."},
    {t:"Why trade", d:2, q:"In the 'different technology' story, labor in the developed country is assumed to be…", a:"More productive than in the less developed country", w:["Less productive","Equally productive","Unemployed"], e:"Same tastes, different technology."},
    {t:"PPF & prices", d:1, q:"The curve showing all combinations of two goods a country can produce is the…", a:"Production possibility frontier (PPF)", w:["Demand curve","Gravity model","Circular flow"], e:"The slides plot textiles against computers."},
    {t:"PPF & prices", d:2, q:"Under autarky, the production possibility frontier also shows…", a:"The consumption possibilities", w:["The free trade price","Exports","The tariff level"], e:"With no trade, production = consumption."},
    {t:"PPF & prices", d:2, q:"The price of one good measured in units of another good, not money, is the…", a:"Relative price", w:["Money price","Tariff","Exchange rate"], e:"'The RELATIVE price of computers in terms of textiles (not money!!)'."},
    {t:"PPF & prices", d:2, q:"The slope of the production possibility frontier shows…", a:"The relative price (opportunity cost) of one good in terms of the other", w:["The country's GDP","The tariff rate","The number of workers"], e:"Slope 2/1 in the LDC vs 1/2 in the developed country."},
    {t:"PPF & prices", d:2, q:"The relative price of a good BEFORE trade opens is its…", a:"Autarky price", w:["Free trade price","World price","Tariff price"], e:"The free trade price must lie between the two autarky prices."},
    {t:"PPF & prices", d:2, q:"Case: In the less developed country, you must give up 2 textiles to get 1 computer. Computers there are relatively…", a:"Expensive", w:["Cheap","Free","Equal in price to textiles"], e:"A high relative price means a high opportunity cost."},
    {t:"PPF & prices", d:2, q:"Case: In the developed country, you give up only half a textile to get 1 computer. Computers there are relatively…", a:"Cheap", w:["Expensive","Free","Taxed"], e:"So the developed country has a comparative advantage in computers."},
    {t:"PPF & prices", d:2, q:"Computers are relatively cheap in the developed country. So the developed country has a…", a:"Comparative advantage in computers", w:["Comparative advantage in textiles","Comparative advantage in both","No advantage"], e:"Low relative price = low opportunity cost."},
    {t:"PPF & prices", d:2, q:"The less developed country is 'LESS BAD' at textiles. So it has a…", a:"Comparative advantage in textiles", w:["Absolute advantage in textiles","Comparative advantage in computers","No advantage"], e:"Being less bad at something is enough."},
    {t:"PPF & prices", d:2, q:"The developed country can produce more textiles AND more computers than the less developed country. It has…", a:"An absolute advantage in both goods", w:["A comparative advantage in both goods","An absolute advantage in computers only","No advantage"], e:"But comparative advantage only in computers."},
    {t:"Free trade", d:2, q:"When the two countries open to free trade, the free-trade relative price must lie…", a:"Between the two autarky prices", w:["Above both autarky prices","Below both autarky prices","Exactly at one country's autarky price"], e:"Otherwise one country wouldn't want to trade."},
    {t:"Free trade", d:3, q:"True or false: The free-trade relative price can lie outside the range of the two autarky prices.", tf:false, e:"It must lie between them."},
    {t:"Free trade", d:2, q:"After free trade opens, what does the developed country specialize in?", a:"Computers", w:["Textiles","Both equally","Neither"], e:"Its comparative advantage."},
    {t:"Free trade", d:2, q:"After free trade opens, the developed country exports ___ and imports ___.", a:"Computers; textiles", w:["Textiles; computers","Both goods; nothing","Nothing; both goods"], e:"It exports its comparative-advantage good."},
    {t:"Free trade", d:2, q:"After free trade opens, the less developed country exports ___ and imports ___.", a:"Textiles; computers", w:["Computers; textiles","Both goods; nothing","Nothing; both goods"], e:"It exports its comparative-advantage good."},
    {t:"Free trade", d:2, q:"After trade opens, the countries' consumption possibilities…", a:"Rise, so neither can be worse off", w:["Fall for the poorer country","Stay the same","Rise only for the richer country"], e:"'Possibilities have clearly risen. So can't be worse off!!'"},
    {t:"Free trade", d:2, q:"In the textiles and computers example, who gains from trade?", a:"Both countries", w:["Only the developed country","Only the less developed country","Neither"], e:"Both end up consuming more of both goods."},
    {t:"Free trade", d:3, q:"True or false: A country with an absolute advantage in both goods cannot gain from trade.", tf:false, e:"The developed country is better at both but still gains by specializing in computers."},
    {t:"Free trade", d:3, q:"Case: The less developed country can now buy a computer for fewer textiles than it cost at home. This is…", a:"A gain from trade: importing at a lower opportunity cost", w:["A loss from trade","A tariff","Autarky"], e:"The free-trade price is better than its autarky price."},
    {t:"Free trade", d:2, q:"Under comparative advantage, each country should specialize in the good with…", a:"The lowest opportunity cost", w:["The highest money price","The most workers","The highest tariff"], e:"That's the Ricardian rule."},
    {t:"Free trade", d:2, q:"Case: Each country produces only the good it has a comparative advantage in, then exchanges. This is…", a:"Specialization and trade", w:["Autarky","Protectionism","Import substitution"], e:"The basis of gains from trade."},
    {t:"Factor endowments", d:1, q:"The amounts of capital, labour and land a country has are its…", a:"Factor endowments", w:["Production possibilities","Tastes","Relative prices"], e:"Lecture 4's fourth reason to trade."},
    {t:"Factor endowments", d:2, q:"A good made mostly with machines and equipment is…", a:"Capital-intensive", w:["Labour-intensive","Land-intensive","Tariff-intensive"], e:"Computers in the slides."},
    {t:"Factor endowments", d:2, q:"A good made mostly with workers is…", a:"Labour-intensive", w:["Capital-intensive","Technology-intensive","Import-intensive"], e:"Textiles in the slides."},
    {t:"Factor endowments", d:2, q:"Case: A country has lots of capital compared to labour. It is…", a:"Capital-abundant", w:["Labour-abundant","Land-scarce","In autarky"], e:"The developed country in the slides."},
    {t:"Factor endowments", d:2, q:"A capital-abundant country can produce relatively MORE of which good?", a:"The capital-intensive good", w:["The labour-intensive good","Neither good","Only services"], e:"The developed country produces more computers."},
    {t:"Factor endowments", d:2, q:"With free trade, a labour-abundant country exports…", a:"The labour-intensive good", w:["The capital-intensive good","Nothing","Capital"], e:"The less developed country exports textiles."},
    {t:"Factor endowments", d:2, q:"Both countries gain by producing more of the good that uses their…", a:"Abundant factor", w:["Scarce factor","Imported factor","Cheapest technology"], e:"Then they trade."},
    {t:"Factor endowments", d:3, q:"If capital and labour were used in the same ratio in both industries, the PPF would be…", a:"A straight line", w:["Bowed outward","Vertical","Horizontal"], e:"'Move in a straight line either way along the production frontier.'"},
    {t:"Factor endowments", d:3, q:"Case: A labour-abundant country shifts toward capital-intensive computers. Why does output rise only a little?", a:"Scarce capital is spread thinner, so capital per worker falls", w:["Workers stop working","Tariffs rise","Computers become labour-intensive"], e:"From the 'Alternative explanation' slide."},
    {t:"Factor endowments", d:3, q:"True or false: If technology and tastes are the same everywhere, there is no reason to trade.", tf:false, e:"Different factor endowments still create comparative advantage."},
    {t:"Factor endowments", d:3, q:"Differences in factor endowments were probably believed to be the main source of gains from trade in…", a:"The original EU", w:["NAFTA","The first wave of globalization","Mercantilist Europe"], e:"Last content slide of Lecture 4."},
    {t:"Factor endowments", d:2, q:"Case: Two countries with identical technology and tastes still have different PPFs. The reason is…", a:"Different factor endowments", w:["Different tariffs","Different exchange rates","Different populations only"], e:"Different endowments mean different production possibilities."}
  ]
},
{
  id: 5, code: "L5", title: "Simple Trade",
  sub: "Intraindustry trade, economies of scale, firm location, industrial policy, WTO rules",
  quip: "Same industry, different vibes. That's intraindustry trade.",
  qs: [
    {t:"Intra vs inter", d:2, q:"Why do the slides say comparative advantage has a 'mixed record' at explaining trade?", a:"It is hard to measure, and many countries export the same goods they import", w:["It has been disproven","It only applies to services","It ignores tariffs"], e:"A large share of world trade isn't described well by comparative advantage alone."},
    {t:"Intra vs inter", d:1, q:"Exports and imports of the SAME products is…", a:"Intraindustry trade", w:["Interindustry trade","Autarky","Vertical FDI"], e:"E.g. aircraft traded both ways between the U.S. and the EU."},
    {t:"Intra vs inter", d:1, q:"Exports and imports of DIFFERENT products is…", a:"Interindustry trade", w:["Intraindustry trade","External economies of scale","Monopolistic competition"], e:"E.g. cell phones out, copper and oil in."},
    {t:"Intra vs inter", d:2, q:"Case: Germany sells cars to Japan and buys cars from Japan. This is…", a:"Intraindustry trade", w:["Interindustry trade","Autarky","An export subsidy"], e:"Same product, both directions."},
    {t:"Intra vs inter", d:2, q:"Case: A country exports cotton and imports machinery. This is…", a:"Interindustry trade", w:["Intraindustry trade","Horizontal FDI","External economies of scale"], e:"Different products in each direction."},
    {t:"Intra vs inter", d:2, q:"Intraindustry trade is most common between…", a:"High-income, advanced economies", w:["Low-income countries","Countries in autarky","Closed economies"], e:"From the slides."},
    {t:"Intra vs inter", d:3, q:"If 'industry' is defined more broadly, measured intraindustry trade…", a:"Rises", w:["Falls","Stays the same","Disappears"], e:"Under 'office machinery', computers and pencil sharpeners are the same industry."},
    {t:"Intra vs inter", d:3, q:"Which is NOT a condition where intraindustry trade is greater?", a:"Countries less open to trade", w:["More scope for product differentiation","High-technology industries","More foreign investment"], e:"It is greater in countries MORE open to trade."},
    {t:"Intra vs inter", d:2, q:"Case: A country imports sports cars and exports trucks. This shows the role of…", a:"Product differentiation", w:["Absolute advantage","Quotas","Autarky"], e:"More scope for differentiation means more intraindustry trade."},
    {t:"Intra vs inter", d:2, q:"Intraindustry trade is encouraged by…", a:"Internal economies of scale", w:["High tariffs","Perfect competition","Autarky"], e:"Slide: 'Intraindustry trade is encouraged when there are internal economies of scale.'"},
    {t:"Intra vs inter", d:2, q:"Case: The U.S. and Canada both export AND import passenger cars and vehicle parts with each other. This shows…", a:"Intraindustry trade is very important", w:["Trade is mainly interindustry","Comparative advantage explains everything","Autarky"], e:"The U.S.–Canada case study."},
    {t:"New trade theory", d:2, q:"Trade models based on internal and external economies of scale are called…", a:"New Trade Theory", w:["Mercantilism","Absolute advantage theory","The gravity model"], e:"Developed to explain intraindustry trade."},
    {t:"New trade theory", d:3, q:"New Trade Theory extends trade theory beyond which models?", a:"The Ricardian and Heckscher-Ohlin (HO) models", w:["The gravity and circular flow models","Smith's and Krugman's models","The IMF and WTO models"], e:"To account for intraindustry trade."},
    {t:"Economies of scale", d:1, q:"As a FIRM grows, its average cost of production falls. This is…", a:"Internal economies of scale", w:["External economies of scale","Diseconomies of scale","Knowledge spillovers"], e:"Depends on the size of the individual firm."},
    {t:"Economies of scale", d:1, q:"As an INDUSTRY grows, average cost falls for individual firms. This is…", a:"External economies of scale", w:["Internal economies of scale","Monopoly","Product differentiation"], e:"Depends on the size of the industry."},
    {t:"Economies of scale", d:2, q:"Case: Only a few giant firms can build jet aircraft, because bigger firms have much lower average costs. This is…", a:"Internal economies of scale", w:["External economies of scale","Perfect competition","Interindustry trade"], e:"Autos and jet aircraft are the slide examples."},
    {t:"Economies of scale", d:3, q:"Case: Many small craft breweries in one region all get cheaper inputs and skilled workers as the industry grows. This is…", a:"External economies of scale", w:["Internal economies of scale","Monopoly","Oligopoly"], e:"Software, music and craft beer are the slide examples."},
    {t:"Economies of scale", d:3, q:"Under INTERNAL economies of scale, markets are usually…", a:"Not perfectly competitive", w:["Perfectly competitive","Always monopolies","Closed to trade"], e:"Under EXTERNAL economies of scale, markets often stay perfectly competitive."},
    {t:"Economies of scale", d:3, q:"True or false: With external economies of scale, each firm has a strong incentive to become large.", tf:false, e:"'Firms do not have an incentive to get large.' That's internal EOS."},
    {t:"Economies of scale", d:2, q:"External economies of scale are described as…", a:"External to the firm but internal to the industry", w:["Internal to the firm, external to the industry","External to the country","Internal to the government"], e:"Exact slide wording."},
    {t:"Market structures", d:1, q:"A market with only ONE firm is a…", a:"Monopoly", w:["Oligopoly","Monopolistic competition","Perfect competition"], e:"Basic definition."},
    {t:"Market structures", d:2, q:"Case: A few large firms each plan strategy based on what the others will do. This market is…", a:"Oligopoly", w:["Monopoly","Monopolistic competition","Perfect competition"], e:"A small number of strategic firms."},
    {t:"Market structures", d:2, q:"Case: Many coffee shop brands each have loyal customers but compete with similar shops nearby. This market is…", a:"Monopolistic competition", w:["Oligopoly","Monopoly","Perfect competition"], e:"Brands give a small monopoly, but close substitutes compete."},
    {t:"Market structures", d:2, q:"Monopolistic competition relies on…", a:"Product differentiation", w:["Identical products","Government ownership","High tariffs"], e:"Brands and close substitutes."},
    {t:"Gains", d:2, q:"Which is NOT a gain from intraindustry trade?", a:"Higher prices for consumers", w:["Lower costs and prices","More variety for consumers","A chance for domestic firms to expand"], e:"Bigger markets bring more scale economies and more competition."},
    {t:"Gains", d:2, q:"A larger market from intraindustry trade means…", a:"More economies of scale and more competition", w:["Fewer firms and higher prices","Less variety","Higher average costs"], e:"So lower average costs and lower prices."},
    {t:"Gains", d:2, q:"Case: After trade opens, shoppers can choose among many more brands of cars. This gain is…", a:"Increased consumer choice (variety)", w:["Economies of scale only","Higher tariffs","Rent seeking"], e:"'An increase in consumer choices. There is more variety in the market.'"},
    {t:"Location", d:2, q:"A firm with internal economies of scale that cannot build a plant in every market should…", a:"Locate near the largest market", w:["Locate where labor is cheapest","Build many small plants","Stay in autarky"], e:"Too many small plants would lose the scale advantage."},
    {t:"Location", d:2, q:"Why is most foreign investment directed to high-income countries?", a:"They have larger markets", w:["They have the cheapest labor","They have the highest tariffs","They have more natural resources"], e:"Internal EOS plus transportation costs pull firms to big markets."},
    {t:"Location", d:3, q:"Case: A firm builds its plant where wages are higher because it is close to its customers. Why?", a:"To avoid high transportation costs", w:["To get higher tariffs","To lower product variety","Because of quotas"], e:"Avoiding transport costs can outweigh higher labor costs."},
    {t:"Location", d:3, q:"Case: A country's manufacturing serves only its own national market, and one capital city grows into a giant mega-city. The slides explain this with…", a:"Internal economies of scale and transportation costs", w:["External economies of scale from software","Export processing zones","Free trade agreements"], e:"The Mexico City case."},
    {t:"Location", d:2, q:"A zone where plants can import inputs tariff-free as long as they export the output is an…", a:"Export processing zone (EPZ)", w:["Free trade agreement","Customs union","Industrial cluster"], e:"Mexico's EPZ plants are called maquiladoras."},
    {t:"Location", d:2, q:"Case: Export-processing plants whose main market is a neighboring country choose to locate near that border. Why?", a:"To be close to their market and cut transportation costs", w:["Because wages are highest there","Because tariffs are highest there","Because of knowledge spillovers only"], e:"Maquiladoras clustered in the border region."},
    {t:"External EOS", d:2, q:"Which is NOT a driver of external economies of scale?", a:"Firm-level mass production", w:["Pooling of labor markets for specialized skills","Pooling of input markets for specialized inputs","Knowledge spillovers between firms"], e:"Firm-level scale is INTERNAL EOS."},
    {t:"External EOS", d:2, q:"Case: Firms cluster in one area because many workers with specialized skills live there. This driver is…", a:"Pooling of labor markets", w:["Pooling of input markets","Knowledge spillovers","Internal economies of scale"], e:"One of the three drivers of external EOS."},
    {t:"External EOS", d:2, q:"Case: Firms cluster near specialized parts suppliers that serve the whole industry. This driver is…", a:"Pooling of input markets", w:["Pooling of labor markets","Knowledge spillovers","Rent seeking"], e:"One of the three drivers of external EOS."},
    {t:"External EOS", d:2, q:"Case: Engineers at nearby firms share ideas, so new knowledge spreads quickly. This driver is…", a:"Knowledge spillovers", w:["Pooling of input markets","Coordination problems","Internal economies of scale"], e:"One of the three drivers of external EOS."},
    {t:"External EOS", d:2, q:"External economies of scale tend to lead to…", a:"Geographical concentration", w:["Firms spreading out evenly","Monopoly","Autarky"], e:"Silicon Valley, Hollywood, Nashville."},
    {t:"External EOS", d:2, q:"Case: Movie studios cluster in one city because talent and suppliers are already there. This is an example of…", a:"External economies of scale", w:["Internal economies of scale","A quota","Interindustry trade"], e:"Hollywood is a slide example."},
    {t:"External EOS", d:2, q:"Case: A group of firms ends up in one area by chance, and then attracts more firms. This is…", a:"Historical accident", w:["Industrial policy","Rent seeking","Product differentiation"], e:"Historical accident may play a role in where industries locate."},
    {t:"External EOS", d:2, q:"Case: The first country to learn a production process stays ahead by keeping one step in front. This is…", a:"A learning curve", w:["A quota","A trade deficit","Monopolistic competition"], e:"'Whoever learns first keeps that advantage by staying one step ahead.'"},
    {t:"External EOS", d:3, q:"True or false: Trade with external economies of scale always creates gains for every country.", tf:false, e:"'Trade with external EOS may in some cases create losses.'"},
    {t:"External EOS", d:3, q:"Case: A latecomer could eventually make widgets better, but cheap imports from the experienced leader keep it from ever starting. This shows…", a:"Trade with external economies of scale can create losses", w:["Comparative advantage always wins","Tariffs never help","Interindustry trade"], e:"The widgets example."},
    {t:"Industrial policy", d:1, q:"Government policies to support the development of a particular industry are…", a:"Industrial policies", w:["Trade agreements","Monetary policies","Capital controls"], e:"For a new industry or an existing one."},
    {t:"Industrial policy", d:2, q:"Case: A government supports clean energy and new generations of motor vehicles. This is…", a:"Industrial policy", w:["Monetary policy","Free trade","A quota"], e:"U.S. examples from the slides."},
    {t:"Industrial policy", d:2, q:"The rationale for industrial policy is that markets sometimes…", a:"Don't provide the optimal quantity of a good or service", w:["Always produce too much","Are run by the WTO","Ignore prices"], e:"Especially when private and social returns differ."},
    {t:"Industrial policy", d:1, q:"When some costs or benefits are not included in a market transaction, there is…", a:"An externality", w:["A tariff","Economies of scale","Product differentiation"], e:"Externalities are known as market failures."},
    {t:"Industrial policy", d:1, q:"Another name for externalities is…", a:"Market failures", w:["Trade barriers","Economies of scale","Learning curves"], e:"Straight from the slides."},
    {t:"Industrial policy", d:2, q:"Case: Getting vaccinated protects you AND the people around you. This is an example where ___ differ.", a:"Private and social benefits", w:["Private and social costs","Fixed and variable costs","Imports and exports"], e:"The vaccination example."},
    {t:"Industrial policy", d:2, q:"Case: A factory pollutes a river and doesn't pay for the damage. This is an example where ___ differ.", a:"Private and social costs", w:["Private and social benefits","Fixed and variable costs","Exports and imports"], e:"The pollution example."},
    {t:"Industrial policy", d:3, q:"When SOCIAL returns are greater than PRIVATE returns, markets produce…", a:"Too little at too high a cost", w:["Too much at too low a cost","The optimal amount","Nothing"], e:"The opposite happens when social returns are smaller."},
    {t:"Industrial policy", d:3, q:"When social returns are LESS than private returns, markets produce…", a:"Too much at too low a cost", w:["Too little at too high a cost","The optimal amount","Only exports"], e:"The professor will flip this one on you."},
    {t:"Industrial policy", d:2, q:"Case: A new product (like the personal computer) creates profits for its maker and new knowledge others can use. This is…", a:"Knowledge spillovers", w:["Coordination problems","Capital market imperfections","Rent seeking"], e:"A reason private and social returns differ."},
    {t:"Industrial policy", d:2, q:"Case: Electric cars won't sell without charging stations, and nobody builds stations without electric cars. This is…", a:"A coordination problem", w:["A knowledge spillover","A capital market imperfection","External economies of scale"], e:"Both must be created at the same time."},
    {t:"Industrial policy", d:2, q:"Case: Banks lack information, so people with profitable ideas can't get loans. This is…", a:"A capital market imperfection", w:["A coordination problem","A knowledge spillover","Rent seeking"], e:"A reason private and social returns differ."},
    {t:"Industrial policy", d:2, q:"Case: A government buys locally made buses to encourage the bus industry. This industrial policy tool is…", a:"Government purchases", w:["Tariffs on services","Floating exchange rates","Rent seeking"], e:"Listed among industrial policy tools."},
    {t:"Industrial policy", d:2, q:"Which is NOT listed as an industrial policy tool?", a:"Nationalizing all private firms", w:["Tax breaks and subsidies","Selling foreign currency at a low rate","Allowing firms to collude to pool resources"], e:"Others: keeping foreign products out, foreign market info, loans and guarantees, government purchases."},
    {t:"Industrial policy", d:3, q:"WTO agreements allow subsidies for…", a:"Precompetitive research and development, but not commercial products", w:["Commercial products, but not R&D","Any product","Nothing at all"], e:"The distinction is hard to make in practice."},
    {t:"Industrial policy", d:2, q:"Case: Firms spend money lobbying for government subsidies instead of becoming more productive. This is…", a:"Rent seeking", w:["Knowledge spillover","Learning curve","Product differentiation"], e:"A practical obstacle and a 'con' of industrial policy."},
    {t:"Industrial policy", d:3, q:"Case: A policy builds a domestic steel industry, and car makers then pay more for steel. Who is hurt?", a:"Downstream firms", w:["Foreign steel makers only","Nobody","The government only"], e:"'Downstream firms may be hurt.'"},
    {t:"Industrial policy", d:2, q:"Which is a 'PRO' argument for industrial policy?", a:"Information gaps and coordination problems make markets slow or ineffective", w:["It causes rent seeking","We don't know which industries to fund","Its record is mixed"], e:"The other three are on the 'con' side."},
    {t:"Industrial policy", d:2, q:"Which is a 'CON' argument against industrial policy?", a:"The market is imperfect but better than a government committee", w:["Developing countries benefit from a selective boost","Most countries have used these policies","Coordination problems slow markets"], e:"Cons: rent seeking, picking winners is hard, mixed record."},
    {t:"WTO rules", d:2, q:"Case: A WTO rule stops a country from requiring foreign investors to use local inputs or hit export targets. This agreement is…", a:"TRIMS (Trade Related Investment Measures)", w:["TRIPS","SCM","GATT"], e:"Designed to ensure national treatment for foreign investments."},
    {t:"WTO rules", d:2, q:"Case: A WTO rule bans subsidies that hurt firms in foreign markets. This agreement is…", a:"SCM (Subsidies and Countervailing Measures)", w:["TRIMS","TRIPS","NAFTA"], e:"Runs parallel to TRIMS."},
    {t:"WTO rules", d:2, q:"Case: A WTO rule makes every country enforce patents, copyrights and trademarks. This agreement is…", a:"TRIPS (Trade-Related Aspects of Intellectual Property Rights)", w:["TRIMS","SCM","GATT"], e:"Also restricts reverse engineering."},
    {t:"WTO rules", d:3, q:"Which is NOT part of TRIPS?", a:"Requiring foreign firms to transfer technology", w:["Patents and copyrights","Restrictions on reverse engineering","Geographical designations"], e:"TRIPS LIMITS requirements that foreign firms transfer technology."},
    {t:"WTO rules", d:2, q:"Treating foreign investments the same as domestic ones is called…", a:"National treatment", w:["Most-favored nation","Rent seeking","Product differentiation"], e:"TRIMS is designed to ensure national treatment for foreign investments."},
    {t:"WTO rules", d:2, q:"What is the main controversy about these WTO rules?", a:"They may limit developing countries' ability to support development", w:["They raise tariffs too much","They ban all trade","They favor small farmers"], e:"Also: do they protect multinational profits at host citizens' expense?"}
  ]
},
{
  id: 6, code: "L6", title: "FDI",
  sub: "GDP, types and motives of foreign investment, effects, TNCs",
  quip: "Greenfield, brownfield, your grades: redfield.",
  qs: [
    {t:"GDP", d:1, q:"The GDP equation on the slides is…", a:"Consumption + investment + government spending + (exports − imports)", w:["Consumption + savings + taxes","Exports − imports + FDI","Investment + government spending − consumption"], e:"GDP = C + I + G + (X − M)."},
    {t:"GDP", d:1, q:"Case: Households buy food, clothes and haircuts. In the GDP equation this is…", a:"Consumption", w:["Investment","Government spending","Net exports"], e:"Personal spending on currently produced goods and services."},
    {t:"GDP", d:2, q:"Case: A firm buys new machines for its factory. In the GDP equation this is…", a:"Investment", w:["Consumption","Government spending","Net exports"], e:"The I in GDP."},
    {t:"GDP", d:2, q:"Case: The state builds roads and bridges. In the GDP equation this is…", a:"Government spending", w:["Investment by firms","Consumption","Net exports"], e:"The G in GDP."},
    {t:"GDP", d:2, q:"Exports minus imports is called…", a:"Net exports", w:["Consumption","Investment","Capital flows"], e:"The (X − M) term."},
    {t:"GDP", d:3, q:"Case: Households spend more, but only on imported goods. Why doesn't GDP rise?", a:"The spending cancels out through the imports term", w:["Imports are not counted at all","It is counted twice","It raises investment instead"], e:"'If consumption is of imported items, then these figures would cancel in the equation.'"},
    {t:"GDP", d:2, q:"Case: People raise consumption by spending their savings. Why do the slides call this a problem?", a:"Spending down savings can't continue forever", w:["It always causes deflation","It lowers exports","It is banned by the WTO"], e:"'Also could mean spending savings… another problem.'"},
    {t:"GDP", d:2, q:"Case: A country's recovery is driven mainly by growing household spending. Which GDP component is driving growth?", a:"Consumption", w:["Government spending","Net exports","Imports"], e:"The Lithuania case."},
    {t:"GDP", d:3, q:"Case: A country with little FDI exports a renewable resource and spends the earnings on public infrastructure. Which GDP component does that spending raise?", a:"Government spending", w:["Consumption","Imports","Portfolio investment"], e:"The Bhutan case: lumber exports fund government spending on infrastructure."},
    {t:"GDP", d:3, q:"Case: A country grows without much FDI because its people are non-materialistic and import little. This keeps which term small?", a:"Imports", w:["Exports","Government spending","Investment"], e:"The Bhutan case: few imports."},
    {t:"Direction of FDI", d:1, q:"What encourages FDI most, according to the slides?", a:"Predictability (stability)", w:["High tariffs","A small population","Uncertain policies"], e:"'PREDICTABILITY! Stable countries draw FDI.'"},
    {t:"Direction of FDI", d:2, q:"Case: A country's rules on licensing, trade, labor and finance are detailed and keep changing. Its effect on foreign investment is to…", a:"Hamper it", w:["Attract it","Have no effect","Double it"], e:"Detailed controls and uncertain policies hamper foreign investment."},
    {t:"Direction of FDI", d:2, q:"Legal institutions encourage FDI by…", a:"Protecting property and contract rights of foreign investors", w:["Raising tariffs","Banning profit repatriation","Fixing exchange rates"], e:"And by creating legal foundations for market-oriented reform."},
    {t:"Direction of FDI", d:3, q:"True or false: A communist state can never attract FDI.", tf:false, e:"With some market reform, communist states can draw FDI (Vietnam is the slide example)."},
    {t:"Direction of FDI", d:2, q:"Historically, most FDI has gone to…", a:"Developed nations", w:["Developing nations","Communist states","Closed economies"], e:"Developed nations still get the largest share, though developing countries get more than before."},
    {t:"Investment types", d:1, q:"Flows of capital from one nation to another in exchange for significant ownership stakes are…", a:"International investment", w:["International trade","Foreign aid","Tariff revenue"], e:"Slide definition."},
    {t:"Investment types", d:2, q:"Which is NOT one of the four categories of foreign investment?", a:"Tariff revenue", w:["Commercial loans","Official loans","Foreign portfolio investment"], e:"The four: commercial loans, official loans, FDI, foreign portfolio investment."},
    {t:"Investment types", d:2, q:"Case: A foreign bank lends money to a company in another country. This is a…", a:"Commercial loan", w:["Official loan","Foreign direct investment","Portfolio investment"], e:"Bank loans to foreign businesses or governments."},
    {t:"Investment types", d:2, q:"Case: A developed country's government gives development assistance to a developing country. This is an…", a:"Official loan", w:["Commercial loan","FDI","Portfolio investment"], e:"From the four categories slide."},
    {t:"Investment types", d:2, q:"Case: An investor gains a lasting interest and control in a company abroad. This is…", a:"Foreign direct investment (FDI)", w:["Foreign portfolio investment","A commercial loan","An official loan"], e:"Lasting interest + control = FDI."},
    {t:"Investment types", d:2, q:"Case: An investor buys easily traded foreign shares with no controlling stake. This is…", a:"Foreign portfolio investment", w:["Foreign direct investment","Greenfield investment","An official loan"], e:"More easily traded, less permanent, no control."},
    {t:"Investment types", d:3, q:"Case: An investor buys a small minority of a foreign firm's shares and has no say in management. This is best classified as…", a:"Portfolio investment", w:["FDI","Greenfield FDI","Vertical FDI"], e:"FDI needs a stake large enough for direct control."},
    {t:"Investment types", d:2, q:"Investing in a foreign company for the purpose of managerial and production control is…", a:"FDI", w:["Portfolio investment","Official lending","Offshoring"], e:"Exact slide wording."},
    {t:"Investment types", d:3, q:"When a foreign company owns enough stock (10% or more) to directly control a subsidiary, the two firms are classified as a…", a:"Multinational corporation", w:["Portfolio investor","Joint government","Holding loan"], e:"10% or more is deemed sufficient for direct control."},
    {t:"Investment types", d:2, q:"A company controlled by a holding company is a…", a:"Subsidiary", w:["Parent company","Portfolio","Cartel"], e:"From 'Defining FDI'."},
    {t:"Motives", d:1, q:"Case: A firm invests abroad to reach a new market with more people to buy its goods. This motive is…", a:"Market-seeking", w:["Resource-seeking","Efficiency-seeking","Strategic asset-seeking"], e:"New market, more buyers."},
    {t:"Motives", d:2, q:"Case: An oil company invests abroad to get access to oil and minerals. This motive is…", a:"Resource-seeking", w:["Market-seeking","Efficiency-seeking","Strategic asset-seeking"], e:"Access to natural resources."},
    {t:"Motives", d:3, q:"Case: A tech firm opens a research lab abroad to tap foreign brainpower. This motive is…", a:"Strategic asset-seeking", w:["Efficiency-seeking","Market-seeking","Resource-seeking"], e:"Knowledge is a strategic asset, not a natural resource."},
    {t:"Motives", d:2, q:"Case: A firm moves production abroad for cheaper labor. This motive is…", a:"Efficiency-seeking", w:["Market-seeking","Resource-seeking","Strategic asset-seeking"], e:"Cheaper labor = efficiency-seeking."},
    {t:"Motives", d:2, q:"Case: Countries remove limits on cross-border capital movements, and foreign investment surges. This reason is…", a:"Financial liberalization", w:["Rising protectionism","Higher tariffs","Import quotas"], e:"One of three reasons foreign investment increased dramatically."},
    {t:"Motives", d:2, q:"Which is NOT a reason foreign investment increased dramatically?", a:"Rising global tariffs", w:["Attractiveness of higher profit","The end of the Cold War","Financial liberalization"], e:"Those three are the slide's reasons."},
    {t:"Motives", d:2, q:"Case: After a long political divide ends, many new countries open up to foreign investors. This reason for rising investment is…", a:"The end of the Cold War", w:["Financial volatility","Repatriation of profits","Rent seeking"], e:"Listed with higher profit and financial liberalization."},
    {t:"Motivation & constraints", d:2, q:"Which is a MOTIVATION for FDI?", a:"Increasing operating efficiency", w:["Cultural differences","Governmental differences","Different consumer tastes"], e:"Motivations: resources, new markets, efficiency. The rest are constraints."},
    {t:"Motivation & constraints", d:3, q:"Which is a CONSTRAINT on FDI, not a motivation?", a:"Cultural differences in business ethics and protocols", w:["New markets","Natural or human resources","Increasing operating efficiency"], e:"Constraints: uncertainties, different tastes, cultural differences, governmental differences."},
    {t:"Motivation & constraints", d:2, q:"Case: A food company finds consumers abroad want completely different flavors from those at home. This is a…", a:"Constraint on FDI", w:["Motivation for FDI","Technology transfer","Capital inflow"], e:"Different consumer tastes in different places."},
    {t:"Effects", d:2, q:"Case: A foreign firm's new factory brings modern machines and know-how to the host country. This benefit is…", a:"Technology transfer", w:["Financial volatility","Loss of sovereignty","Repatriation of profits"], e:"FDI often introduces world-class technologies and expertise."},
    {t:"Effects", d:2, q:"Case: Foreign money flows into a country to build businesses. This positive effect is…", a:"Capital inflows", w:["Capital flight","Financial volatility","Repatriation"], e:"A positive effect of foreign investment."},
    {t:"Effects", d:2, q:"Case: A foreign-owned plant hires thousands of local workers. This positive effect is…", a:"Employment generation (job creation)", w:["Job loss from offshoring","Loss of sovereignty","Financial volatility"], e:"Most FDI creates new businesses in the host country."},
    {t:"Effects", d:2, q:"Case: Foreign investors pull money out suddenly and the host country's markets swing wildly. This negative effect is…", a:"Financial volatility", w:["Technology transfer","Capital inflows","Employment generation"], e:"A negative effect of foreign investment."},
    {t:"Effects", d:2, q:"Case: Big foreign firms gain so much influence that the host government struggles to set its own policies. This negative effect is…", a:"Loss of national sovereignty", w:["Technology transfer","Market-seeking","Economic growth"], e:"A negative effect of foreign investment."},
    {t:"Effects", d:2, q:"Case: A firm in the investing country closes a domestic plant after moving production abroad. This negative effect is…", a:"Job loss due to offshoring", w:["Technology transfer","Capital inflows","Strategic asset-seeking"], e:"A negative effect of foreign investment."},
    {t:"Effects", d:2, q:"Case: Foreign investment opens a host country up to new markets and its output grows faster. This benefit is…", a:"Economic growth", w:["Financial volatility","Loss of sovereignty","Repatriation of profits"], e:"'Countries receiving FDI often experience higher economic growth by opening it up to new markets.'"},
    {t:"Effects", d:1, q:"Which are the three key benefits of FDI listed?", a:"Economic growth, job creation and technology transfer", w:["Higher tariffs, more quotas, less trade","Inflation, debt and volatility","Lower wages, fewer jobs, less technology"], e:"From the key benefits slide."},
    {t:"TNCs", d:1, q:"A company that operates and invests in many countries is a…", a:"Transnational corporation (TNC)", w:["Holding loan","State monopoly","Portfolio fund"], e:"TNCs drive world investment."},
    {t:"TNCs", d:2, q:"Most TNCs and FDI originate in…", a:"Developed countries", w:["Developing countries","Communist states","Closed economies"], e:"And most FDI is concentrated in the developed world."},
    {t:"TNCs", d:2, q:"Case: A TNC trains local workers and upgrades their skills. How does this affect development?", a:"It aids development by educating and upgrading labor", w:["It bankrupts local producers","It repatriates profits","It causes loss of sovereignty"], e:"One of the ways TNCs can aid development."},
    {t:"TNCs", d:2, q:"Case: A TNC pays local taxes and its workers save locally. How does this affect development?", a:"It aids development as a source of local savings and taxes", w:["It harms development through repatriation","It causes volatility","It has no effect"], e:"Listed among the TNC benefits."},
    {t:"TNCs", d:2, q:"Case: A TNC sends most of its profits back to its home country. This is…", a:"Repatriation of profits", w:["Technology transfer","Capital inflow","Market-seeking"], e:"One way TNCs can be counterproductive to development."},
    {t:"TNCs", d:2, q:"Case: Small local shops close because they can't compete with a giant TNC. This is…", a:"Bankrupting local producers", w:["Technology transfer","Knowledge spillover","Employment generation"], e:"The other way TNCs can be counterproductive."},
    {t:"Types of FDI", d:1, q:"Case: A company builds a brand-new production facility abroad. This is…", a:"Greenfield FDI", w:["Brownfield FDI","Portfolio investment","An official loan"], e:"Greenfield = build new."},
    {t:"Types of FDI", d:2, q:"Case: A firm buys a controlling stake in an existing foreign company. This is…", a:"Brownfield FDI (cross-border merger and acquisition)", w:["Greenfield FDI","Portfolio investment","A commercial loan"], e:"Brownfield = buy existing."},
    {t:"Types of FDI", d:3, q:"True or false: An automaker building a brand-new factory abroad is brownfield FDI.", tf:false, e:"Building new = GREENFIELD. Buying existing = brownfield."},
    {t:"Types of FDI", d:2, q:"Case: A company invests abroad in the SAME business it runs at home. This is…", a:"Horizontal FDI", w:["Vertical FDI","Brownfield FDI","Portfolio investment"], e:"Same business = horizontal."},
    {t:"Types of FDI", d:2, q:"Case: A company invests in a foreign business that supplies its inputs or distributes its products. This is…", a:"Vertical FDI", w:["Horizontal FDI","Greenfield FDI","Market-seeking FDI"], e:"Supplier or distributor = vertical."},
    {t:"Types of FDI", d:3, q:"Case: A car maker buys a tire supplier abroad. This is…", a:"Vertical FDI", w:["Horizontal FDI","Portfolio investment","An official loan"], e:"The tire maker is a supplier in its production chain."},
    {t:"Types of FDI", d:3, q:"Case: A soft-drink company opens a bottling plant in a foreign country because shipping drinks there is too expensive. This is…", a:"Horizontal FDI", w:["Vertical FDI","Portfolio investment","Outsourcing"], e:"Horizontal FDI arises when serving a market by exports is costly (transport costs, trade barriers)."},
    {t:"Types of FDI", d:3, q:"Horizontal FDI mainly arises because…", a:"Serving the overseas market by exports is expensive (transport costs, trade barriers)", w:["Production costs differ between countries","Labor is cheaper abroad","The firm needs a supplier"], e:"Vertical FDI is the one driven by production cost differences."},
    {t:"Types of FDI", d:3, q:"Vertical FDI is mainly driven by…", a:"Production cost differences between countries", w:["Transport costs and trade barriers","Tariffs on finished goods","Cultural affinity"], e:"For stages of production that can be done in another location."},
    {t:"Types of FDI", d:3, q:"Case: A firm signs a contract with an INDEPENDENT foreign company to produce for it, without owning it. This is…", a:"Foreign outsourcing (offshoring)", w:["Vertical FDI","Greenfield FDI","Brownfield FDI"], e:"No ownership, just a contract. So it's not FDI."},
    {t:"Types of FDI", d:2, q:"The lecture's overall conclusion is that international investment benefits…", a:"Both the investing country and the host country", w:["Only the investing country","Only the host country","Neither"], e:"From the 'Overall' slide."}
  ]
}
];
